import{_ as a,o as t,c as s,a2 as o}from"./chunks/framework.C2TvIV46.js";const m=JSON.parse('{"title":"Dynamic strings","description":"","frontmatter":{},"headers":[],"relativePath":"language/enums/dynamic-strings.md","filePath":"language/enums/dynamic-strings.md"}'),n={name:"language/enums/dynamic-strings.md"};function l(d,e,r,c,i,g){return t(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="dynamic-strings" tabindex="-1">Dynamic strings <a class="header-anchor" href="#dynamic-strings" aria-label="Permalink to &quot;Dynamic strings&quot;">​</a></h1><p>Operand type for actions that show text with optional runtime substitutions. In ManagedMegalo grammar this appears as <code>&lt;dynamic_string&gt;</code>; on the wire it is stored as <code>c_dynamic_string</code> — a string-table index plus up to two replaceable tokens.</p><p>A dynamic string is always a <a href="/MegaloEvolved/beta/docs/language/elements/string-table">string table</a> symbol or an <a href="/MegaloEvolved/beta/docs/language/syntax#string-table-symbols-vs-inline-literals">inline literal</a>, followed by zero, one, or two reference operands that fill <code>%</code> placeholders in that text.</p><h2 id="placeholders" tabindex="-1">Placeholders <a class="header-anchor" href="#placeholders" aria-label="Permalink to &quot;Placeholders&quot;">​</a></h2><p>Scan the string left to right for <code>%</code> followed by a known letter. Each match consumes the next action operand after the string. At most <strong>two</strong> placeholders are allowed; a third is a compile error (<code>Too many replacement tokens!</code>). Unknown <code>%X</code> sequences are ignored and do not consume an operand.</p><table tabindex="0"><thead><tr><th>Specifier</th><th>Operand type</th><th>Example operand</th></tr></thead><tbody><tr><td><code>%n</code></td><td><a href="/MegaloEvolved/beta/docs/language/references#reference-types">Number</a> (custom variable)</td><td><code>score_to_win_round</code>, <code>1</code>, <code>global.my_counter</code></td></tr><tr><td><code>%p</code></td><td><a href="/MegaloEvolved/beta/docs/language/references#reference-types">Player</a></td><td><code>current_player</code>, <code>killing_player</code></td></tr><tr><td><code>%t</code></td><td><a href="/MegaloEvolved/beta/docs/language/references#team-designators">Team</a></td><td><code>attackers</code>, <code>current_player.team</code></td></tr><tr><td><code>%o</code></td><td><a href="/MegaloEvolved/beta/docs/language/references#reference-types">Object</a></td><td><code>current_object</code>, <code>global.flag</code></td></tr><tr><td><code>%s</code></td><td><a href="/MegaloEvolved/beta/docs/language/references#reference-types">Timer</a></td><td><code>global.round_timer</code>, <code>sudden_death_timer</code></td></tr></tbody></table><p><code>%s</code> is <strong>not</strong> a string (unlike C <code>printf</code>). It inserts a timer — likely “<strong>s</strong>econds”, since <code>%t</code> already means team. The engine formats the timer’s remaining time into the slot.</p><p>Operand order matches placeholder order in the string — not the order of letters in the table above.</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">action player_set_objective current_player </span><span class="megalo-string">&quot;+</span><span class="megalo-regexp">%n</span><span class="megalo-string">&quot;</span><span class="megalo-text"> score_to_win_round</span></span>
<span class="line"><span class="megalo-text">action hud_post_message everyone none </span><span class="megalo-string">&quot;</span><span class="megalo-regexp">%p</span><span class="megalo-string"> scored!&quot;</span><span class="megalo-text"> scoring_player</span></span>
<span class="line"><span class="megalo-text">action navpoint_set_text current_object </span><span class="megalo-string">&quot;</span><span class="megalo-regexp">%n</span><span class="megalo-string"> s&quot;</span><span class="megalo-text"> global</span><span class="megalo-operator">.</span><span class="megalo-text">countdown</span></span></code></pre></div><p>At runtime the engine substitutes each token into the corresponding <code>%</code> slot (for example <code>&quot;+%n&quot;</code> with <code>score_to_win_round</code> → <code>+25</code>).</p><h2 id="persistent-vs-transient" tabindex="-1">Persistent vs transient <a class="header-anchor" href="#persistent-vs-transient" aria-label="Permalink to &quot;Persistent vs transient&quot;">​</a></h2><p>Some actions treat the dynamic string as <strong>persistent</strong> — the text must remain valid after the trigger finishes. Those actions reject <strong>transient</strong> variable references in the token operands (<code>Can&#39;t use transient variables when reading a persistent string</code>).</p><table tabindex="0"><thead><tr><th>Mode</th><th>Actions</th><th>Transient tokens</th></tr></thead><tbody><tr><td>Persistent</td><td><a href="/MegaloEvolved/beta/docs/language/actions/hud-widget-set-text"><code>hud_widget_set_text</code></a>, <a href="/MegaloEvolved/beta/docs/language/actions/hud-widget-set-value"><code>hud_widget_set_value</code></a>, <a href="/MegaloEvolved/beta/docs/language/actions/navpoint-set-text"><code>navpoint_set_text</code></a>, <a href="/MegaloEvolved/beta/docs/language/actions/player-set-objective"><code>player_set_objective</code></a>, <a href="/MegaloEvolved/beta/docs/language/actions/player-set-objective-allegiance"><code>player_set_objective_allegiance</code></a></td><td>Forbidden</td></tr><tr><td>Transient</td><td><a href="/MegaloEvolved/beta/docs/language/actions/hud-post-message"><code>hud_post_message</code></a>, <a href="/MegaloEvolved/beta/docs/language/actions/print-variable"><code>print_variable</code></a>, <a href="/MegaloEvolved/beta/docs/language/actions/saved-film-insert-marker"><code>saved_film_insert_marker</code></a></td><td>Allowed</td></tr></tbody></table><h2 id="used-by" tabindex="-1">Used by <a class="header-anchor" href="#used-by" aria-label="Permalink to &quot;Used by&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Grammar</th></tr></thead><tbody><tr><td><a href="/MegaloEvolved/beta/docs/language/actions/hud-post-message"><code>hud_post_message</code></a></td><td><code>&lt;team_or_player_target&gt; &lt;sound&gt; &lt;dynamic_string&gt;</code></td></tr><tr><td><a href="/MegaloEvolved/beta/docs/language/actions/print-variable"><code>print_variable</code></a></td><td><code>&lt;dynamic_string&gt;</code></td></tr><tr><td><a href="/MegaloEvolved/beta/docs/language/actions/hud-widget-set-text"><code>hud_widget_set_text</code></a></td><td><code>&lt;hud_widget_name&gt; &lt;dynamic_string&gt;</code></td></tr><tr><td><a href="/MegaloEvolved/beta/docs/language/actions/hud-widget-set-value"><code>hud_widget_set_value</code></a></td><td><code>&lt;hud_widget_name&gt; &lt;dynamic_string&gt;</code></td></tr><tr><td><a href="/MegaloEvolved/beta/docs/language/actions/navpoint-set-text"><code>navpoint_set_text</code></a></td><td><code>&lt;object&gt; &lt;dynamic_string&gt;</code></td></tr><tr><td><a href="/MegaloEvolved/beta/docs/language/actions/player-set-objective"><code>player_set_objective</code></a></td><td><code>&lt;player&gt; &lt;dynamic_string&gt;</code></td></tr><tr><td><a href="/MegaloEvolved/beta/docs/language/actions/player-set-objective-allegiance"><code>player_set_objective_allegiance</code></a></td><td><code>&lt;player&gt; &lt;dynamic_string&gt;</code></td></tr><tr><td><a href="/MegaloEvolved/beta/docs/language/actions/saved-film-insert-marker"><code>saved_film_insert_marker</code></a></td><td><code>&lt;offset (s)&gt; &lt;label&gt;</code> — <code>&lt;label&gt;</code> is parsed as a dynamic string</td></tr></tbody></table><h2 id="localization" tabindex="-1">Localization <a class="header-anchor" href="#localization" aria-label="Permalink to &quot;Localization&quot;">​</a></h2><p>When the string is a string-table symbol, every language translation must declare the <strong>same</strong> placeholder types in the <strong>same</strong> order. Mismatched <code>%</code> tokens across languages produce a compile error. Prefer symbols over inline literals for shipped text — see <a href="/MegaloEvolved/beta/docs/language/compiler-settings#string-literal-strictness">String literal strictness</a>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">string_table</span><span class="megalo-text"> </span><span class="megalo-enumMember">english</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-variable">obj_score</span><span class="megalo-text"> </span><span class="megalo-string">&quot;+</span><span class="megalo-regexp">%n</span><span class="megalo-string">&quot;</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-variable">msg_scored</span><span class="megalo-text"> </span><span class="megalo-string">&quot;</span><span class="megalo-regexp">%p</span><span class="megalo-string"> scored!&quot;</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">trigger</span><span class="megalo-text"> player_scored</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">player_set_objective</span><span class="megalo-text"> current_player </span><span class="megalo-variable">obj_score</span><span class="megalo-text"> </span><span class="megalo-variable">score_to_win_round</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">hud_post_message</span><span class="megalo-text"> </span><span class="megalo-enumMember">everyone</span><span class="megalo-text"> </span><span class="megalo-variable">none</span><span class="megalo-text"> </span><span class="megalo-variable">msg_scored</span><span class="megalo-text"> scoring_player</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/MegaloEvolved/beta/docs/language/syntax#format-placeholders">Syntax — Format placeholders</a></li><li><a href="/MegaloEvolved/beta/docs/language/elements/string-table">String table</a></li><li><a href="/MegaloEvolved/beta/docs/language/references">References</a></li></ul>`,21)])])}const h=a(n,[["render",l]]);export{m as __pageData,h as default};
